<?php
if($role==='admin'){$news=$pdo->query('SELECT * FROM announcements ORDER BY publish_date DESC,created_at DESC')->fetchAll();}else{$q=$pdo->prepare("SELECT * FROM announcements WHERE status='published' AND publish_date<=CURDATE() AND (expires_on IS NULL OR expires_on>=CURDATE()) ORDER BY publish_date DESC,created_at DESC");$q->execute();$news=$q->fetchAll();}
?>
<?php if($role==='admin'):?><section class="panel"><div class="panel-head"><div><h2>Post an employee notice</h2><p>Share an event, update, or message that employees can read in their workspace.</p></div></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="announcement_save"><label>Title *<input name="title" maxlength="180" required </label><label>Publish date<input type="date" name="publish_date" value="<?=date('Y-m-d')?>" required></label><label>Expires on<input type="date" name="expires_on"></label><label>Status<select name="status"><option value="published">Publish</option><option value="draft">Save as draft</option></select></label><label class="wide">Message *<textarea name="body" rows="4" required></textarea></label><div class="form-actions"><button class="button primary">Save notice</button></div></form></section><?php endif;?>
<section class="panel"><div class="panel-head"><div><h2><?= $role==='admin'?'Notices and announcements':'Notices for employees'?></h2><p><?=count($news)?> <?=count($news)===1?'notice':'notices'?></p></div></div><?php if(!$news):?><div class="empty-state"><span class="empty-icon"><?=ems_icon('megaphone')?></span><h3>No notices yet</h3><p>Updates posted by the administrator will appear here.</p></div><?php else:?><div class="notice-list"><?php foreach($news as $n):?><article class="notice-card"><div class="notice-meta"><span><?=e(date('M j, Y',strtotime($n['publish_date'])))?></span><?php if($role==='admin'):?><span class="badge <?= $n['status']==='published'?'success':'muted'?>"><?=e(ucfirst($n['status']))?></span><?php endif;?></div><h3><?=e($n['title'])?></h3><p><?=nl2br(e($n['body']))?></p><?php if($n['expires_on']):?><small>Visible through <?=e(date('M j, Y',strtotime($n['expires_on'])))?></small><?php endif;?><?php if($role==='admin'):?><details class="notice-edit"><summary>Edit or remove</summary><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="announcement_save"><input type="hidden" name="id" value="<?=$n['id']?>"><label>Title<input name="title" value="<?=e($n['title'])?>" required></label><label>Publish date<input type="date" name="publish_date" value="<?=e($n['publish_date'])?>" required></label><label>Expires on<input type="date" name="expires_on" value="<?=e($n['expires_on']??'')?>"></label><label>Status<select name="status"><option value="published" <?=$n['status']==='published'?'selected':''?>>Publish</option><option value="draft" <?=$n['status']==='draft'?'selected':''?>>Draft</option></select></label><label class="wide">Message<textarea name="body" rows="3" required><?=e($n['body'])?></textarea></label><button class="button secondary">Update notice</button></form><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="announcement_delete"><input type="hidden" name="id" value="<?=$n['id']?>"><button class="text-action reject">Delete notice</button></form></details><?php endif;?></article><?php endforeach;?></div><?php endif;?></section>
<?php if($role!=='employee'):?>
<section class="panel"><div class="panel-head"><div><h2>Upcoming public holidays</h2><p>Dates selected by your administrator</p></div><?php if($role==='admin'):?><a class="text-link" href="<?=e($base.'/admin/holidays.php')?>">View calendar →</a><?php endif;?></div><?php $upcoming=$pdo->query('SELECT holiday_date,holiday_name FROM public_holidays WHERE holiday_date>=CURDATE() ORDER BY holiday_date LIMIT 6')->fetchAll();if(!$upcoming):?><p class="muted-text">No upcoming public holidays have been set.</p><?php else:?><div class="holiday-upcoming"><?php foreach($upcoming as $h):?><div><b><?=e(date('D, M j, Y',strtotime($h['holiday_date'])))?></b><span><?=e($h['holiday_name'])?></span></div><?php endforeach;?></div><?php endif;?></section>
<?php endif;?>
